import math


def evaluate(expr: str) -> int:
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")

    # Tokenize
    tokens: list[tuple[str, int | str]] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            start = i
            while i < n and "0" <= expr[i] <= "9":
                i += 1
            tokens.append(("NUM", int(expr[start:i])))
        elif ch in "+-*/%^!()":
            if ch == "(" and tokens and tokens[-1][0] in ("NUM", ")", "!"):
                tokens.append(("*", "*"))
            tokens.append((ch, ch))
            i += 1
        else:
            raise ValueError(f"Invalid character: {ch!r}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0
    num_tokens = len(tokens)

    def parse_expr() -> int:
        nonlocal pos
        val = parse_term()
        while pos < num_tokens and tokens[pos][0] in ("+", "-"):
            op = tokens[pos][0]
            pos += 1
            right = parse_term()
            if op == "+":
                val += right
            else:
                val -= right
        return val

    def parse_term() -> int:
        nonlocal pos
        val = parse_unary()
        while pos < num_tokens and tokens[pos][0] in ("*", "/", "%"):
            op = tokens[pos][0]
            pos += 1
            right = parse_unary()
            if op == "*":
                val *= right
            elif op == "/":
                if right == 0:
                    raise ValueError("Division by zero")
                q = abs(val) // abs(right)
                val = -q if (val < 0) ^ (right < 0) else q
            else:
                if right == 0:
                    raise ValueError("Remainder by zero")
                r = abs(val) % abs(right)
                val = -r if val < 0 else r
        return val

    def parse_unary() -> int:
        nonlocal pos
        chain: list[tuple[int, int]] = []
        while True:
            neg_count = 0
            while pos < num_tokens and tokens[pos][0] == "-":
                neg_count += 1
                pos += 1
            base = parse_postfix()
            chain.append((neg_count, base))
            if pos < num_tokens and tokens[pos][0] == "^":
                pos += 1
            else:
                break

        neg_count, val = chain[-1]
        if neg_count % 2 == 1:
            val = -val
        for i in range(len(chain) - 2, -1, -1):
            if val < 0:
                raise ValueError("Negative exponent")
            neg_count, base = chain[i]
            val = base**val
            if neg_count % 2 == 1:
                val = -val
        return val

    def parse_postfix() -> int:
        nonlocal pos
        val = parse_primary()
        while pos < num_tokens and tokens[pos][0] == "!":
            pos += 1
            if val < 0:
                raise ValueError("Factorial of a negative number")
            val = math.factorial(val)
        return val

    def parse_primary() -> int:
        nonlocal pos
        if pos >= num_tokens:
            raise ValueError("Unexpected end of expression")
        tok_type, tok_val = tokens[pos]
        if tok_type == "NUM":
            pos += 1
            return int(tok_val)
        if tok_type == "(":
            pos += 1
            val = parse_expr()
            if pos >= num_tokens or tokens[pos][0] != ")":
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return val
        raise ValueError(f"Unexpected token: {tok_val!r}")

    result = parse_expr()
    if pos != num_tokens:
        raise ValueError(f"Unexpected token: {tokens[pos][1]!r}")
    return result
